/* R1328 — profile/membership flow quality and state hardening */
(()=>{'use strict';
const RELEASE='FR-NAV1.30.28-HF3.13.10';
const path=(location.pathname.replace(/\/+$/,'/')||'/');
const q=(s,r=document)=>r.querySelector(s),qa=(s,r=document)=>[...r.querySelectorAll(s)];
const norm=s=>String(s||'').replace(/\s+/g,' ').trim();
const params=new URLSearchParams(location.search);
function markRelease(){const m=q('meta[name="franklin-release"]');if(m)m.content=RELEASE;document.documentElement.dataset.franklinRelease=RELEASE}
function membershipEntry(){if(!['/membership-start/','/business-membership/','/es/iniciar-membresia/'].includes(path))return;const card=q('.hf310-decision-card');const cta=q('a.button.primary',card||document);if(cta&&/start membership|iniciar membres/i.test(norm(cta.textContent))){cta.href='/claim-profile/?next=membership';cta.textContent=document.documentElement.lang==='es'?'Elegir mi perfil primero':'Choose my profile first'} }
function claimFlow(){if(path!=='/claim-profile/')return;const next=params.get('next');const results=q('[data-hf310-claim-results]');const selected=q('[data-hf310-claim-selected]');if(next==='membership'){const hero=q('.hf37-claim-hero .wrap');if(hero&&!q('.r1328-context',hero)){const n=document.createElement('p');n.className='r1328-context';n.innerHTML='<strong>Membership setup:</strong> choose the public profile you want to continue with. Choosing a listing does not verify that you represent it; representation is confirmed separately before checkout.';hero.append(n)}}
  let status=q('[data-r1328-claim-status]');if(results&&!status){status=document.createElement('p');status.className='fine-print r1328-result-status';status.dataset.r1328ClaimStatus='1';status.setAttribute('role','status');status.setAttribute('aria-live','polite');results.insertAdjacentElement('afterend',status)}
  const sync=()=>{if(!results)return;const buttons=qa('button.hf310-claim-result',results);buttons.forEach(b=>{const tail=qa('span',b).at(-1),current=norm(tail?.textContent);if(tail&&current!=='Choose profile'&&/choose|this is my profile/i.test(current))tail.textContent='Choose profile'});if(status){if(buttons.length)status.textContent=`${buttons.length} matching profile${buttons.length===1?'':'s'} shown. Choose the correct public listing; representation is verified separately.`;else if(/no matching profile/i.test(norm(results.textContent)))status.textContent='No matching public profile was found. You can request a free basic public profile.';else status.textContent=''}
    if(selected&&!selected.hidden){const manage=qa('a.button',selected).find(a=>/manage this profile|membership/i.test(norm(a.textContent))||/membership-enroll/.test(a.getAttribute('href')||''));if(manage&&/membership-enroll/.test(manage.getAttribute('href')||'')){const desired=next==='membership'?'Continue membership setup with this profile':'Manage or continue with this profile';if(norm(manage.textContent)!==desired)manage.textContent=desired;if(next==='membership'&&!manage.href.includes('source='))manage.href+=(manage.href.includes('?')?'&':'?')+'source=claim-profile'}}};
  if(results)new MutationObserver(sync).observe(results,{childList:true,subtree:true,characterData:true});if(selected)new MutationObserver(sync).observe(selected,{attributes:true,childList:true,subtree:true,characterData:true});sync()}
function previewFlow(){if(path!=='/member-profile-preview/')return;for(const name of ['youtube','x','tiktok','threads']){const el=q(`[name="${name}"]`);if(el){el.type='url';el.autocomplete='url';el.inputMode='url';el.setAttribute('aria-describedby','r1328-link-review-note')}}const form=q('[data-r28-preview-form]');if(form&&!q('#r1328-link-review-note',form)){const n=document.createElement('p');n.id='r1328-link-review-note';n.className='fine-print r1328-link-note';n.textContent='Links entered here are preview proposals. They are not treated as verified or published until the applicable review succeeds.';const action=qa('details',form).find(d=>/action links|online presence/i.test(norm(q('summary',d)?.textContent)));(q('.hf310-editor-body',action||document)||form).append(n)}}
function enrollFlow(){if(path!=='/membership-enroll/')return;const progress=q('.r37-member-progress');const root=q('[data-membership-live-root]');if(!progress||!root)return;const labels=['1 · Choose profile','2 · Account','3 · Confirm representation','4 · Membership','5 · Benefits & billing'];const spans=qa(':scope > span',progress);spans.forEach((s,i)=>{if(labels[i])s.textContent=labels[i]});progress.classList.add('r1328-enroll-progress');
  const profile=params.get('profile');const checkout=params.get('checkout');if(!profile&&checkout!=='success'){root.hidden=true;let pre=q('[data-r1328-enroll-preflight]');if(!pre){pre=document.createElement('section');pre.className='r37-member-step r1328-enroll-preflight';pre.dataset.r1328EnrollPreflight='1';pre.innerHTML='<h2>Choose your Franklin profile first</h2><p>Membership is tied to one public Franklin profile. Start by choosing the matching business, professional practice or organization. Choosing a listing does not grant management access; representation is verified separately before checkout.</p><div class="r37-member-actions"><a class="button primary" href="/claim-profile/?next=membership">Find or manage my profile</a><a class="button" href="/membership-start/">Review membership details</a></div><p class="fine-print">Factual corrections and public-profile removal remain free and do not require membership.</p>';root.insertAdjacentElement('beforebegin',pre)}setProgress(1);return}
  root.hidden=false;let trust=q('[data-r1328-enroll-trust]');if(!trust){trust=document.createElement('p');trust.className='r1328-enroll-trust fine-print';trust.dataset.r1328EnrollTrust='1';trust.textContent='Selecting a profile does not prove representation. Franklin confirms profile authority before checkout. Do not pay again if a payment outcome is uncertain.';progress.insertAdjacentElement('afterend',trust)}
  function setProgress(current,completeThrough=current-1){spans.forEach((s,i)=>{const step=i+1;s.classList.toggle('is-complete',step<=completeThrough);s.classList.toggle('is-current',step===current);if(step===current)s.setAttribute('aria-current','step');else s.removeAttribute('aria-current')})}
  function sync(){const text=norm(root.textContent);qa('.r37-search-result',root).forEach(b=>{const tail=qa('span',b).at(-1);if(tail&&/this is my profile/i.test(norm(tail.textContent)))tail.textContent='Choose profile'});if(/membership active/i.test(text)){setProgress(5,5);return}if(/continue\s*[—-]\s*\$35\/year|profile verified.*continue to membership/i.test(text)){setProgress(4,3);return}if(/confirming that you represent|request profile access|representation/i.test(text)&&!/create an account or sign in/i.test(text)){setProgress(3,2);return}if(/create an account or sign in/i.test(text)){setProgress(2,1);return}if(/find your profile/i.test(text)){setProgress(1,0);return}setProgress(profile?2:1,profile?1:0)}
  new MutationObserver(sync).observe(root,{childList:true,subtree:true,characterData:true});sync()}
function init(){markRelease();membershipEntry();claimFlow();previewFlow();enrollFlow()}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();
